// Fixtures generated by Obsidian-AI 7b7e735's actual exportChat.ts serializer.
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { toStoredSession, fromStoredSession, sessionRuntimeState, restoreRuntimeState } from './conversationFormat';
import { buildConversationHistory } from './conversationHistory';
import { normalizePersistedSession } from './sessionPersistence';
import { parseSessionArchive } from '../utils/importChat';
import { serializeToJSON, serializeToJSONL, serializeToMarkdown } from '../utils/exportChat';
import { LocalStoragePersistenceAdapter } from '../adapters/LocalStoragePersistence';
import { ChatEngine } from './ChatEngine';
import type { LLMAdapter } from './types';
const read = (extension: string) => readFileSync(`${process.cwd()}/src/core/__fixtures__/obsidian-rich.${extension}`, 'utf8');
const original = JSON.parse(read('json'));
describe('canonical Obsidian-AI conversation format', () => {
    for (const extension of ['json', 'jsonl'])
        it(`preserves rich ${extension} through import, normalization, storage and export`, async () => {
            const imported = parseSessionArchive(read(extension))[0];
            const normalized = normalizePersistedSession(imported).session!;
            const persistence = new LocalStoragePersistenceAdapter({ ownerId: `parity-${extension}` });
            await persistence.saveSession(normalized);
            const loaded = (await persistence.loadSessions())[0];
            const exported = JSON.parse(serializeToJSON([loaded], 'single'));
            // Saving updates only the timestamp; all reference data remains intact.
            expect(exported).toEqual({ ...original, updatedAt: loaded.updatedAt });
            expect(JSON.parse(localStorage.getItem(`super-chat:owner:parity-${extension}:session:rich`)!)).toEqual(exported);
            expect(exported.turns).toBeUndefined();
            expect(exported.conversation).toBeUndefined();
            expect(exported.ownership).toBeUndefined();
        });
    it('matches the reference single JSONL and Markdown serializers exactly', () => {
        const session = fromStoredSession(original);
        expect(serializeToJSONL([session], 'single')).toBe(read('jsonl'));
        expect(serializeToMarkdown([session], 'single')).toBe(read('md'));
    });
    it('preserves empty and multiple sessions in both formats', () => {
        const empty = fromStoredSession({ ...original, id: 'empty', messages: [] });
        for (const scope of ['single', 'all'] as const)
            for (const serialize of [serializeToJSON, serializeToJSONL]) {
                const sessions = scope === 'single' ? [empty] : [empty, fromStoredSession(original)];
                const result = parseSessionArchive(serialize(sessions, scope)).map(toStoredSession);
                expect(result.map(s => s.messages.length)).toEqual(scope === 'single' ? [0] : [0, 4]);
            }
    });
    it('keeps cancellation/retrieval/runtime fields outside the canonical record', () => {
        const session = fromStoredSession(original);
        session.messages[1].status = 'streaming';
        session.messages[1].turnId = 'turn';
        session.archived = true;
        const saved = toStoredSession(session);
        const restored = restoreRuntimeState(fromStoredSession(saved), sessionRuntimeState(session));
        expect(saved).toEqual(original);
        expect(restored.messages[1].status).toBe('streaming');
        expect(restored.archived).toBe(true);
    });
    it('replays complete tool pairs, resolved attachments and skips debug messages', () => {
        const session = fromStoredSession({ ...original, compactionMetadata: undefined });
        const history = buildConversationHistory(session);
        expect(history[0].resolvedParts).toEqual(original.messages[0].resolvedParts);
        expect(history.some(m => m.content === 'Private debug')).toBe(false);
        const parts = JSON.parse(history[1].content);
        expect(parts[1]).toMatchObject({ type: 'tool-call', toolCallId: 'call-1', toolName: 'search_web', providerMetadata: original.messages[1].toolCalls[0].call.providerMetadata });
        expect(JSON.parse(parts[2].output)).toEqual(original.messages[1].toolCalls[0].result);
    });
    it('uses a valid saved compaction summary and ignores it after a source edit', () => {
        const session = fromStoredSession(original);
        expect(buildConversationHistory(session)[0].content).toContain('Use reference format');
        session.messages[0].content = 'Edited';
        expect(buildConversationHistory(session)[0].content).toBe('Edited');
    });
    it('continues an imported conversation through the engine with canonical history', async () => {
        const requests: unknown[] = [];
        const adapter = { getProviders: () => [], getModels: () => [], async *streamChat(messages: unknown) { requests.push(messages); yield 'New answer'; } } as unknown as LLMAdapter;
        const engine = new ChatEngine({ llmAdapter: adapter });
        engine.updateSettings({ enableRAG: false, enableTools: false });
        await engine.importSessions([fromStoredSession({ ...original, compactionMetadata: undefined })]);
        engine.switchSession('rich');
        for await (const _event of engine.sendMessage('Continue')) { /* drain */ }
        const request = JSON.stringify(requests);
        expect(request).toContain('call-1');
        expect(request).toContain('resolvedParts');
        expect(request).not.toContain('Private debug');
        const saved = toStoredSession(engine.getActiveSession()!);
        expect(saved.messages.at(-1)?.content).toBe('New answer');
        expect(saved.modelOverrides).toEqual(original.modelOverrides);
    });
});
it('persists resolved attachment events on the matching visible user message', async () => {
    const adapter = { getProviders: () => [], getModels: () => [], async *streamChat() { yield 'unused'; }, async *streamChatEvents(messages: {
            messageId?: string;
            content: string;
        }[]) { const message = messages.at(-1)!; yield { type: 'message-parts-resolved', messageId: message.messageId, parts: [{ type: 'text', text: message.content }, { type: 'text', text: 'Resolved document' }] }; yield { type: 'text-delta', text: 'Answer' }; } } as unknown as LLMAdapter;
    const engine = new ChatEngine({ llmAdapter: adapter });
    engine.updateSettings({ enableRAG: false, enableTools: false });
    engine.createSession('New');
    for await (const _event of engine.sendMessage('Question')) { /* drain */ }
    expect(toStoredSession(engine.getActiveSession()!).messages[0].resolvedParts).toEqual([{ type: 'text', text: 'Question' }, { type: 'text', text: 'Resolved document' }]);
});
